import { ImageCropper, type CropState } from "march/ui"

// çıkartma yapıcı: gülen yüzü kare kırp, döndür, aynala; altta yuvarlak çıkartma hâlini anlatan satır
// küçük bir satır içi SVG; blob: adresi olarak (data: SVG güvenli sayılmaz, engellenir)
const FACE = URL.createObjectURL(new Blob([`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" fill="#ffd27a"/><circle cx="50" cy="50" r="34" fill="#f2801f"/><circle cx="38" cy="42" r="5" fill="#13233a"/><circle cx="62" cy="42" r="5" fill="#13233a"/><path d="M34 60q16 14 32 0" stroke="#13233a" stroke-width="5" fill="none" stroke-linecap="round"/></svg>`], { type: "image/svg+xml" }))

export function StickerMaker() {
  let $crop: CropState | undefined
  return <div sx={{ flex: "col", gap: 2 }}>
    <ImageCropper src={FACE} alt="Gülen yüz" aspect={1} sliders={["angle"]} hint={false} bind:value={$crop} />
    <span sx={{ text: "sm", color: "muted" }}>
      Çıkartma: {$crop ? `${Math.round($crop.rotate)}° döndü${$crop.flip ? ", aynalandı" : ""}` : "henüz dokunulmadı"}
    </span>
  </div>
}

import { ImageCropper, Button, Card, Avatar, toast, type ImageCropperApi } from "march/ui"

// profil fotoğrafı: dosya seç (ya da örnekle başla), kare kırp, "Kaydet" kırpılmış hâli 256 px genişlikte avatara koyar
// küçük bir satır içi SVG; blob: adresi olarak (data: SVG güvenli sayılmaz, engellenir)
const SAMPLE = URL.createObjectURL(new Blob([`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><rect width="160" height="120" fill="#4cc3e0"/><circle cx="80" cy="52" r="24" fill="#f4ecd8"/><path d="M40 120q40-50 80 0z" fill="#a3338c"/></svg>`], { type: "image/svg+xml" }))

export function AvatarUpload() {
  let $src = SAMPLE
  let $avatar = ""
  let api: ImageCropperApi | undefined
  const choose = (e: Event) => { const f = (e.target as HTMLInputElement).files?.[0]; if (f) $src = URL.createObjectURL(f) }
  const save = async () => {
    const blob = await api?.toBlob("image/png", undefined, 256)
    if (!blob) { toast("Görsel henüz yüklenmedi"); return }
    $avatar = URL.createObjectURL(blob)
    toast("Profil fotoğrafı güncellendi")
  }
  return <Card>
    <div sx={{ flex: "col", gap: 2 }}>
      <div sx={{ flex: ["row", "center"], gap: 2 }}>
        <Avatar name="Deniz Kaya" src={$avatar || undefined} size="lg" />
        <input type="file" accept="image/*" aria-label="Fotoğraf seç" on:change={choose} />
      </div>
      <ImageCropper src={$src} alt="Profil fotoğrafı" aspect={1} aspects={false} preview={false} api={(a) => api = a} />
      <Button on:click={save}>Kaydet</Button>
    </div>
  </Card>
}

import { ImageCropper, Button, Toggle, type CropState, type ImageCropperApi } from "march/ui"

// ImageCropper'ın bütün özellikleri: görsel ve açıklaması, değer (bind:value) ve onChange, kendi oran seçeneklerin,
// en çok yakınlaştırma, önizleme ve boyut yazısı, API (sıfırla), ızgara, ipucu, seçili düğmeler ve kaydırıcılar,
// kendi metinlerin, sınıf, salt okunur, devre dışı ve erişilebilir ad; "Kare" düğmesi sabit oranı (aspect) açar
// küçük bir satır içi SVG; blob: adresi olarak (data: SVG güvenli sayılmaz, engellenir)
const PIC = URL.createObjectURL(new Blob([`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 80"><rect width="120" height="80" fill="#13233a"/><circle cx="30" cy="24" r="8" fill="#ffd27a"/><path d="M0 80l40-40 30 26 20-14 30 28z" fill="#78be3a"/></svg>`], { type: "image/svg+xml" }))
const LABELS = { cropper: "Kırpma tezgâhı", area: "Kırpılacak alan", hint: "Sürükle, + − ile yaklaş", free: "Serbest", aspect: "Oran", rotateLeft: "Sola çevir", rotateRight: "Sağa çevir", mirror: "Aynala", reset: "Baştan", zoom: "Yakınlık", angle: "Eğim", result: "Sonuç" }

export function ImageCropperLab() {
  let $crop: CropState = { zoom: 1.5, rotate: 0, flip: false, x: 0, y: 0, aspect: null, w: 0.8, h: 0.8 }
  let $changes = 0
  let $square = false
  let $locked = false
  let api: ImageCropperApi | undefined
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button size="sm" on:click={() => $square = !$square}>{$square ? "Serbest oran" : "Kare"}</Button>
      <Button size="sm" variant="ghost" on:click={() => api?.reset()}>API ile sıfırla</Button>
      <Toggle label="Kilitle" bind:value={$locked} />
      <span sx={{ text: "sm" }}>dönüş: {$crop.rotate}° · ayna: {$crop.flip ? "evet" : "hayır"} · değişiklik: {$changes}</span>
    </div>
    <ImageCropper
      src={PIC}
      alt="Dağ ve ay"
      bind:value={$crop}
      onChange={() => $changes++}
      aspect={$square ? 1 : undefined}
      aspects={[{ label: "Serbest", value: null }, { label: "2:1", value: 2 }]}
      maxZoom={3}
      preview
      size
      api={(a) => api = a}
      grid
      hint
      tools={["rotateLeft", "rotateRight", "mirror", "reset"]}
      sliders={["zoom", "angle"]}
      labels={LABELS}
      class="lab-crop"
      readonly={$locked}
      disabled={false}
      aria-label="Kapak kırpıcı"
    />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ImageCropperLab } from "./ImageCropperLab.tsx"

// ImageCropperLab'in testleri: kaydedince Testler sekmesinde çalışır
test("sağa çevir 90° döndürür, aynala aynalar", async () => {
  const s = renderTest(() => <ImageCropperLab />)
  await s.click("Sağa çevir")
  expect(s.sees("dönüş: 90°")).toBe(true)
  await s.click("Aynala")
  expect(s.sees("ayna: evet")).toBe(true)
  expect(s.sees("değişiklik: 2")).toBe(true)
})

test("API ile sıfırla başlangıca döndürür", async () => {
  const s = renderTest(() => <ImageCropperLab />)
  await s.click("Sola çevir")
  expect(s.sees("dönüş: -90°")).toBe(true)
  await s.click("API ile sıfırla")
  expect(s.sees("dönüş: 0°")).toBe(true)
})

test("kendi oranları görünür; Kare sabit oranı açınca seçenekler gizlenir", async () => {
  const s = renderTest(() => <ImageCropperLab />)
  expect(s.find("2:1")).not.toBe(null)
  await s.click("Kare")
  expect(s.find("2:1")).toBe(null)
})

test("kilitliyken düğmeler devre dışı", async () => {
  const s = renderTest(() => <ImageCropperLab />)
  await s.click(s.find("Kilitle")!.closest("label")!.querySelector("[role=switch]")!)
  expect(s.find("Sağa çevir")?.hasAttribute("disabled")).toBe(true)
  expect(s.get(".lab-crop")?.className).toContain("is-readonly")
})
